<script setup>
import { computed, ref, onMounted, onBeforeUnmount, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Odometer, Shop, ShoppingBag, TrendCharts, Setting, ArrowDown, Menu, Close, ArrowRight } from '@element-plus/icons-vue'
import { useUserStore } from '@/stores/user'
import ServiceReminder from '@/components/ServiceReminder.vue'
import { visibleNavigation } from '@/lib/navigation'
import { businessLabels, insightPermissions } from '@/lib/business'

const route = useRoute(), user = useUserStore(), icons = { Odometer, Shop, ShoppingBag, TrendCharts, Setting }
const demoMode = import.meta.env.VITE_DEMO_MODE !== 'false'
const media = window.matchMedia('(max-width: 850px)'), drawerOpen = ref(false), compact = ref(media.matches)
const updateMedia = event => { compact.value = event.matches; if (!event.matches) drawerOpen.value = false }
onMounted(() => media.addEventListener('change', updateMedia))
onBeforeUnmount(() => media.removeEventListener('change', updateMedia))
watch(() => route.fullPath, () => { drawerOpen.value = false })
const navigation = computed(() => visibleNavigation(user.canAccessProduct, user.hasPermission))
const businesses = computed(() => ['DINING', 'MALL'].filter(user.canAccessProduct))
const canOverview = computed(() => businesses.value.length && user.hasPermission(insightPermissions))
const selectedBusiness = computed(() => route.path.startsWith('/mall') ? 'MALL' : route.path === '/overview' || route.path.startsWith('/reports') ? route.query.business || 'ALL' : route.path.startsWith('/settings') || route.path.startsWith('/services') || route.path.startsWith('/account') ? 'ALL' : 'DINING')
const section = computed(() => navigation.value.find(item => item.path === route.path || item.children?.some(child => child.path === route.path))?.label || '商户管理')
const displayName = computed(() => user.userInfo?.nickname || user.userInfo?.name || user.userInfo?.username || '商户账号')
const avatar = computed(() => Array.from(displayName.value)[0] || '商')
</script>

<template>
  <div class="commerce-shell" @keydown.esc="drawerOpen = false">
    <button v-if="compact && drawerOpen" class="nav-backdrop" aria-label="关闭导航遮罩" @click="drawerOpen = false" />
    <aside id="merchant-navigation" class="commerce-sidebar" :class="{ 'is-open': drawerOpen }" :inert="compact && !drawerOpen" :aria-hidden="compact && !drawerOpen">
      <RouterLink class="brand" :to="user.homePath()"><span class="brand-symbol"><el-icon><Shop /></el-icon></span><span><strong>商家经营台</strong><small>让每天的经营更清晰</small></span></RouterLink>
      <el-button v-if="compact" class="nav-close" text :icon="Close" aria-label="关闭导航" @click="drawerOpen = false" />
      <div class="nav-caption">工作空间</div>
      <el-scrollbar class="nav-scroll"><el-menu :default-active="route.path" :default-openeds="navigation.filter(n => n.children?.some(c => c.path === route.path)).map(n => n.path)" router unique-opened class="commerce-nav"><template v-for="item in navigation" :key="item.path"><el-sub-menu v-if="item.children" :index="item.path"><template #title><el-icon><component :is="icons[item.icon]" /></el-icon><span>{{ item.label }}</span></template><el-menu-item v-for="child in item.children" :key="child.path" :index="child.path">{{ child.label }}</el-menu-item></el-sub-menu><el-menu-item v-else :index="item.path"><el-icon><component :is="icons[item.icon]" /></el-icon><span>{{ item.label }}</span></el-menu-item></template></el-menu></el-scrollbar>
      <div class="sidebar-foot"><i /><span>{{ demoMode ? '演示工作空间' : '商户工作空间' }}</span><small>{{ businesses.length }} 项业务</small></div>
    </aside>
    <div class="commerce-body">
      <header class="topbar"><div class="location"><el-button v-if="compact" text :icon="Menu" aria-label="打开导航" aria-controls="merchant-navigation" :aria-expanded="drawerOpen" @click="drawerOpen = true" /><span class="section-label">{{ section }}</span><el-icon class="breadcrumb-arrow"><ArrowRight /></el-icon><strong>{{ route.meta.title || '经营总览' }}</strong></div><div class="topbar-right"><span v-if="demoMode" class="workspace-tag">演示环境</span><el-dropdown trigger="click"><button class="account-button"><span class="account-avatar">{{ avatar }}</span><span class="account-name">{{ displayName }}<small>{{ user.userInfo?.role === 'admin' ? '店长' : '员工' }}</small></span><el-icon><ArrowDown /></el-icon></button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="$router.push('/account/security')">修改密码</el-dropdown-item><el-dropdown-item divided @click="user.logout()">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header>
      <div v-if="canOverview" class="business-bar"><span>经营范围</span><nav aria-label="切换经营范围"><RouterLink v-if="businesses.length > 1" to="/overview" :class="{ selected: selectedBusiness === 'ALL' }">全店经营</RouterLink><RouterLink v-for="type in businesses" :key="type" :to="{ path: '/overview', query: { business: type } }" :class="{ selected: selectedBusiness === type }">{{ businessLabels[type] }}</RouterLink></nav></div>
      <main class="commerce-main" :class="{ 'cashier-main': route.name === 'PosIndex' }"><ServiceReminder v-if="!user.userInfo?.passwordChangeRequired" /><div v-if="demoMode" class="demo-notice"><span>演示</span>当前使用测试数据，模拟支付不扣款，真实支付和退款未开放。</div><router-view v-slot="{ Component }"><Suspense><component :is="Component" :key="route.fullPath" /><template #fallback><div class="page-fallback">正在准备工作空间…</div></template></Suspense></router-view></main>
    </div>
  </div>
</template>

